export function findRule(id: string): FailureRule | undefined {
  return RULES.find(r => r.id === id);
}

export async function triggerRule(id: string): Promise<void> {
  const rule = findRule(id);
  if (!rule) {
    logger.warn("unknown_rule_triggered", { event: "rule_lookup", error_code: "UNKNOWN_RULE", metadata: { id } });
    return;
  }
  try {
    await rule.remediation();
  } catch (e: any) {
    logger.error("remediation_failed", { event: id, error_code: "REMEDIATION_FAILED", metadata: { error: e.message } });
  }
}